<template>
  <section class="rendering-studio">
    <header class="studio-header">
      <div><strong>{{ t('renderingStudio') }}</strong><small>{{ t('renderingStudioHint') }}</small></div>
      <nav aria-label="Rendering sections"><button v-for="section in sections" :key="section.id" :class="{ active: activeSection === section.id }" @click="activeSection = section.id">{{ t(section.label) }}</button></nav>
    </header>

    <div v-if="activeSection === 'lighting'" class="section-scroll studio-grid">
      <article class="card">
        <header><strong>{{ t('lighting') }}</strong><input v-model="settings.lightingEnabled" type="checkbox"></header>
        <label><span>{{ t('ambientIntensity') }}</span><input v-model.number="settings.ambientIntensity" type="range" min="0" max="2" step="0.05"></label>
        <label><span>{{ t('ambientColor') }}</span><input type="color" :value="hex(settings.ambientColor)" @input="setColor(settings.ambientColor, $event)"></label>
        <label><span>{{ t('shadowQuality') }}</span><select v-model="settings.shadowQuality"><option>Off</option><option>Hard</option><option>Soft</option><option>Ultra</option></select></label>
        <p>{{ t('lightingWorkflowHint') }}</p>
      </article>
      <article class="card">
        <header><strong>{{ t('lightingCapabilities') }}</strong><span :class="capability.path === 'Diagnostic fallback' ? 'warning' : 'good'">{{ capability.path }}</span></header>
        <dl><div><dt>{{ t('rendererBackend') }}</dt><dd>{{ capability.backend }}</dd></div><div><dt>{{ t('maximumTextureSize') }}</dt><dd>{{ capability.maximumTextureSize || 'n/a' }}</dd></div><div><dt>{{ t('normalMaps') }}</dt><dd>{{ capability.backend === 'WebGL2' ? t('supported') : t('fallback') }}</dd></div><div><dt>{{ t('contextRecovery') }}</dt><dd>{{ capability.contextRecovery ? t('supported') : t('unsupported') }}</dd></div></dl>
      </article>
    </div>

    <div v-else-if="activeSection === 'materials'" class="section-scroll material-layout">
      <aside class="card material-list"><header><strong>{{ t('materials') }}</strong><button @click="createMaterial">＋</button></header><button v-for="asset in materialAssets" :key="asset.uuid" :class="{ active: selectedGuid === asset.uuid }" @click="selectedGuid = asset.uuid">{{ asset.name }}</button><p v-if="!materialAssets.length">{{ t('noMaterials') }}</p></aside>
      <main class="card material-properties">
        <header><strong>{{ material.name }}</strong><button class="primary" :disabled="!selectedGuid || hasErrors" @click="saveMaterial">{{ t('validateAndSave') }}</button></header>
        <div class="property-grid">
          <label><span>{{ t('parentMaterial') }}</span><select v-model="material.parentMaterial"><option :value="null">{{ t('none') }}</option><option v-for="asset in parentMaterialAssets" :key="asset.uuid" :value="assetReference(asset.uuid)">{{ asset.name }}</option></select></label>
          <label><span>{{ t('blendMode') }}</span><select v-model="material.blendMode"><option>Alpha</option><option>Additive</option><option>Multiply</option><option>Screen</option></select></label>
          <label><span>{{ t('filterMode') }}</span><select v-model="material.sampling"><option>Linear</option><option>Nearest</option></select></label>
          <label><span>{{ t('colorSpace') }}</span><select v-model="material.colorSpace"><option>sRGB</option><option>Linear</option></select></label>
          <label><span>{{ t('variant') }}</span><select v-model="material.activeVariant"><option value="">{{ t('default') }}</option><option v-for="(_,name) in material.variants" :key="name" :value="name">{{ name }}</option></select></label>
          <label><span>{{ t('colorWrite') }}</span><input v-model="material.writeColor" type="checkbox"></label>
        </div>
        <section class="typed-uniforms">
          <header><strong>{{ t('typedUniforms') }}</strong><span>{{ material.uniformSchema.length }}</span></header><p v-if="!material.uniformSchema.length">{{ t('noReflectedUniforms') }}</p>
          <label v-for="field in material.uniformSchema" :key="field.name"><span :title="field.name">{{ field.label }}</span>
            <input v-if="field.type === 'toggle'" :checked="Boolean(material.uniforms[field.name])" type="checkbox" @change="setToggle(field.name, $event)">
            <select v-else-if="field.type === 'texture'" :value="material.textures[field.name] ?? ''" @change="setTexture(field.name, $event)"><option value="">{{ t('none') }}</option><option v-for="asset in imageAssets" :key="asset.uuid" :value="assetReference(asset.uuid)">{{ asset.name }}</option></select>
            <select v-else-if="field.type === 'enum'" :value="Number(material.uniforms[field.name] ?? 0)" @change="setScalar(field.name, $event, true)"><option v-for="(option,index) in field.options ?? []" :key="option" :value="index">{{ option }}</option></select>
            <input v-else-if="field.type === 'color'" type="color" :value="uniformColor(field.name)" @input="setUniformColor(field.name, $event)">
            <div v-else-if="field.type.startsWith('vector')" class="vector-inputs"><input v-for="index in vectorLength(field.type)" :key="index" type="number" step="0.01" :value="uniformComponent(field.name,index-1)" @input="setUniformComponent(field.name,index-1,$event)"></div>
            <input v-else :type="field.type === 'range' ? 'range' : 'number'" :min="field.minimum" :max="field.maximum" :step="field.step ?? (field.type === 'integer' ? 1 : .01)" :value="Number(material.uniforms[field.name] ?? 0)" @input="setScalar(field.name,$event,field.type === 'integer')">
          </label>
        </section>
      </main>
      <aside class="card preview-card"><header><strong>{{ t('livePreview') }}</strong></header><canvas ref="previewCanvas" width="480" height="280"></canvas><p :class="hasErrors ? 'error' : 'good'">{{ hasErrors ? t('shaderHasErrors') : t('shaderReady') }}</p></aside>
    </div>

    <div v-else-if="activeSection === 'shaders'" class="section-scroll shader-layout">
      <section class="card shader-editor"><header><strong>{{ t('shaderSource') }}</strong><label class="advanced-toggle"><input v-model="advancedMode" type="checkbox">{{ t('advanced') }}</label></header><div class="shader-options"><label><span>{{ t('sharedIncludes') }}</span><span><label v-for="(_,name) in includeLibrary" :key="name" class="check"><input type="checkbox" :checked="material.includes.includes(name)" @change="toggleInclude(name)">{{ name }}</label></span></label></div><textarea v-model="material.fragment" spellcheck="false" @input="schedulePreview"></textarea></section>
      <aside class="card shader-side"><canvas ref="shaderPreviewCanvas" width="420" height="240"></canvas><div class="diagnostics" :class="{ error: hasErrors }"><p v-if="!diagnostics.length">{{ t('shaderReady') }}</p><button v-for="item in diagnostics" :key="`${item.line}:${item.message}`" @click="focusShaderLine(item.line)">{{ item.severity.toUpperCase() }} · L{{ item.line }} · {{ item.message }}</button></div><details v-if="advancedMode" open><summary>{{ t('advancedJsonViews') }}</summary><label>{{ t('uniformsJson') }}<textarea v-model="uniformsJson" rows="5" @change="applyUniforms"></textarea></label><label>{{ t('texturesJson') }}<textarea v-model="texturesJson" rows="4" @change="applyTextures"></textarea></label></details></aside>
    </div>

    <div v-else-if="activeSection === 'graph'" class="section-scroll graph-section">
      <div class="graph-toolbar card"><label><span>{{ t('materialAsset') }}</span><select v-model="selectedGuid"><option v-for="asset in materialAssets" :key="asset.uuid" :value="asset.uuid">{{ asset.name }}</option></select></label><button v-if="!material.graph" class="primary" @click="enableMaterialGraph">{{ t('createVisualGraph') }}</button><button :disabled="!selectedGuid || hasErrors" @click="saveMaterial">{{ t('validateAndSave') }}</button></div>
      <MaterialGraphEditor v-if="material.graph" v-model="material.graph" :layers="material.layers" @update:model-value="schedulePreview" />
      <article class="card layer-editor"><header><strong>{{ t('materialLayers') }}</strong><span>{{ material.layers.length }} / 16</span></header><div class="layer-actions"><button v-for="kind in layerKinds" :key="kind" :disabled="material.layers.length >= 16" @click="addLayer(kind)">＋ {{ t(`materialLayer${kind}`) }}</button></div><div v-for="(layer,index) in material.layers" :key="layer.id" class="layer-row" :class="{ selected: selectedLayerId === layer.id }"><input v-model="layer.enabled" type="checkbox" @change="schedulePreview"><button class="layer-name" @click="selectedLayerId = layer.id"><strong>{{ layer.name }}</strong></button><select v-model="layer.blendMode" @change="schedulePreview"><option>Alpha</option><option>Additive</option><option>Multiply</option><option>Screen</option></select><input v-model.number="layer.opacity" type="range" min="0" max="1" step=".05" @input="schedulePreview"><button @click="moveLayer(index,-1)">↑</button><button @click="moveLayer(index,1)">↓</button><button class="danger" @click="removeLayer(index)">×</button></div><div v-if="selectedLayer" class="layer-details"><label>{{ t('name') }}<input v-model.trim="selectedLayer.name" maxlength="80" @change="schedulePreview"></label><label v-if="selectedLayer.kind !== 'Mask'">{{ t('startColor') }}<input type="color" :value="unitColorHex(selectedLayer.colorA)" @input="setLayerColor(selectedLayer.colorA,$event)"></label><label v-if="selectedLayer.kind === 'Gradient'">{{ t('endColor') }}<input type="color" :value="unitColorHex(selectedLayer.colorB)" @input="setLayerColor(selectedLayer.colorB,$event)"></label><label v-if="selectedLayer.kind === 'Mask'">{{ t('mask') }}<select v-model="selectedLayer.texture" @change="schedulePreview"><option :value="null">{{ t('none') }}</option><option v-for="asset in imageAssets" :key="asset.uuid" :value="assetReference(asset.uuid)">{{ asset.name }}</option></select></label><label v-if="['Palette','Outline','Distortion'].includes(selectedLayer.kind)">{{ t('strength') }}<input v-model.number="selectedLayer.strength" type="number" min="0" max="32" step=".05" @change="schedulePreview"></label><label v-if="selectedLayer.kind === 'Dissolve'">{{ t('threshold') }}<input v-model.number="selectedLayer.threshold" type="range" min="0" max="1" step=".01" @input="schedulePreview"></label><label v-if="selectedLayer.kind === 'Dissolve'">{{ t('softness') }}<input v-model.number="selectedLayer.softness" type="range" min=".001" max="1" step=".01" @input="schedulePreview"></label></div><p v-if="!material.layers.length">{{ t('noMaterialLayers') }}</p><p>{{ materialGraphRecommendation }}</p></article>
    </div>

    <div v-else-if="activeSection === 'particles'" class="section-scroll particle-section">
      <div class="studio-grid"><article class="card"><header><strong>{{ t('particleBudget') }}</strong><span :class="particles.budgetExceeded ? 'error' : 'good'">{{ particles.activeParticles }} / {{ particles.budget }}</span></header><label><span>{{ t('projectParticleBudget') }}</span><input v-model.number="settings.particleBudget" type="number" min="100" max="100000"></label><dl><div><dt>{{ t('emitters') }}</dt><dd>{{ particles.emitterCount }}</dd></div><div><dt>{{ t('particleUpdateTime') }}</dt><dd>{{ particles.updateMs.toFixed(2) }} ms</dd></div><div><dt>{{ t('subemitters') }}</dt><dd>{{ particles.subemissions }}</dd></div><div><dt>CPU / GPU</dt><dd>{{ particles.cpuSimulated }} / {{ particles.gpuRendered }}</dd></div></dl><p>{{ t('particleEditorHint') }}</p></article>
      <article class="card"><header><strong>{{ t('particleWorkflow') }}</strong></header><p>{{ t('particleWorkflowDescription') }}</p><label><span>{{ t('particleSystemAsset') }}</span><select v-model="selectedParticleGuid"><option value="">{{ t('none') }}</option><option v-for="asset in particleAssets" :key="asset.uuid" :value="asset.uuid">{{ asset.name }}</option></select></label><div class="capture-compare"><button @click="createParticleAsset">＋ {{ t('assetFromEmitter') }}</button><button :disabled="!selectedParticleGuid" @click="saveParticleAsset">{{ t('saveAsset') }}</button><button :disabled="!selectedParticleGuid" @click="applyParticleAsset">{{ t('applyAsset') }}</button></div><button @click="openParticleInspector">{{ t('selectParticleEmitter') }}</button></article></div>
      <ParticleGraphEditor v-model="particleGraph" :backend="capability.backend" />
      <article class="card event-timeline"><header><strong>{{ t('particleEvents') }}</strong><span>{{ particles.events.length }}</span></header><p v-if="!particles.events.length">{{ t('noParticleEvents') }}</p><span v-for="event in particles.events.slice(0,12)" :key="`${event.time}:${event.emitterUuid}:${event.kind}`">{{ event.kind }} · {{ event.signal }}</span></article>
    </div>

    <div v-else-if="activeSection === 'post'" class="section-scroll post-layout">
      <article class="card"><header><strong>{{ t('postProcessPresets') }}</strong><input v-model="settings.postProcessing.enabled" type="checkbox"></header><label><span>{{ t('activePreset') }}</span><select v-model="settings.postProcessing.activePreset" @change="applyActivePostPreset"><option v-for="preset in settings.postProcessing.presets" :key="preset.id" :value="preset.id">{{ preset.name }}</option></select></label><div class="property-grid"><label><span>{{ t('exposure') }}</span><input v-model.number="activePostPreset.exposure" type="number" min="-8" max="8" step=".1" @change="syncPostPreset"></label><label><span>{{ t('contrast') }}</span><input v-model.number="activePostPreset.contrast" type="number" min="0" max="4" step=".05" @change="syncPostPreset"></label><label><span>{{ t('saturation') }}</span><input v-model.number="activePostPreset.saturation" type="number" min="0" max="4" step=".05" @change="syncPostPreset"></label><label><span>{{ t('vignette') }}</span><input v-model.number="activePostPreset.vignette" type="range" min="0" max="1" step=".05" @input="syncPostPreset"></label><label><span>{{ t('bloom') }}</span><input v-model.number="activePostPreset.bloom" type="range" min="0" max="2" step=".05" @input="syncPostPreset"></label><label><span>{{ t('blur') }}</span><input v-model.number="activePostPreset.blur" type="range" min="0" max="16" step=".25" @input="syncPostPreset"></label></div><button @click="duplicatePostPreset">＋ {{ t('duplicatePreset') }}</button><p>{{ postCost.passes }} {{ t('passes') }} · {{ postCost.estimatedMsAt1080p }} ms @ 1080p · {{ postCost.recommendation }}</p></article>
      <article class="card"><header><strong>{{ t('cameraVolumes') }}</strong><button @click="addPostVolume">＋</button></header><div v-for="volume in settings.postProcessing.volumes" :key="volume.id" class="volume-card"><label><input v-model="volume.enabled" type="checkbox"><strong>{{ volume.name }}</strong></label><label>{{ t('preset') }}<select v-model="volume.presetId"><option v-for="preset in settings.postProcessing.presets" :key="preset.id" :value="preset.id">{{ preset.name }}</option></select></label><label>{{ t('center') }} X<input v-model.number="volume.center.x" type="number" step=".5">Y<input v-model.number="volume.center.y" type="number" step=".5"></label><label>{{ t('size') }} X<input v-model.number="volume.size.x" type="number" min=".001" step=".5">Y<input v-model.number="volume.size.y" type="number" min=".001" step=".5"></label><label>{{ t('blendDistance') }}<input v-model.number="volume.blendDistance" type="number" min="0" step=".25"></label><label>{{ t('priority') }}<input v-model.number="volume.priority" type="number" min="-1000" max="1000"></label><button class="danger" @click="removePostVolume(volume.id)">{{ t('remove') }}</button></div><p v-if="!settings.postProcessing.volumes.length">{{ t('noCameraVolumes') }}</p></article>
    </div>

    <div v-else-if="activeSection === 'production'" class="section-scroll production-layout">
      <article class="card production-summary" :class="`status-${mediaReport.status}`"><header><div><strong>{{ t('productionMedia') }}</strong><small>{{ t('productionMediaHint') }}</small></div><b>{{ t(`mediaStatus_${mediaReport.status}`) }}</b></header><div class="profile-choice"><button :class="{ active: mediaReport.profile === 'Balanced' }" @click="applyMediaProfile('Balanced')">{{ t('balancedProfile') }}</button><button :class="{ active: mediaReport.profile === 'LowEnd' }" @click="applyMediaProfile('LowEnd')">{{ t('lowEndProfile') }}</button></div><p>{{ t('semanticParityHint') }}</p></article>
      <article class="card readiness-card"><header><strong>{{ t('productionReadiness') }}</strong><span>{{ mediaReport.checks.filter(item=>item.status==='ready').length }} / {{ mediaReport.checks.length }}</span></header><button v-for="item in mediaReport.checks" :key="item.id" :class="['readiness-row',`status-${item.status}`]" @click="focusMediaSubsystem(item.subsystem)"><span><b>{{ t(`mediaCheck_${item.id}`) }}</b><small>{{ item.detail }}</small></span><strong>{{ t(`mediaStatus_${item.status}`) }}</strong></button></article>
      <article class="card"><header><strong>{{ t('textureStreaming') }}</strong><input v-model="settings.textureStreaming.enabled" type="checkbox"></header><label><span>{{ t('streamingMemoryBudget') }}</span><input v-model.number="settings.textureStreaming.memoryBudgetMb" type="number" min="16" max="65536"></label><label><span>{{ t('idleEvictionFrames') }}</span><input v-model.number="settings.textureStreaming.idleFrames" type="number" min="2" max="36000"></label><label><span>{{ t('uploadBudget') }}</span><input v-model.number="settings.textureStreaming.uploadBudgetPerFrame" type="number" min="1" max="4096"></label><label><span>{{ t('preloadMargin') }}</span><input v-model.number="settings.textureStreaming.preloadMargin" type="number" min="1" max="8" step=".25"></label><dl><div><dt>{{ t('residentTextures') }}</dt><dd>{{ stats.textures }}</dd></div><div><dt>{{ t('textureMemory') }}</dt><dd>{{ (stats.textureMemoryBytes/1048576).toFixed(1) }} MB</dd></div><div><dt>{{ t('streamingMisses') }}</dt><dd>{{ stats.streamingMisses }}</dd></div><div><dt>{{ t('textureEvictions') }}</dt><dd>{{ stats.textureEvictions }}</dd></div></dl><p>{{ t('textureStreamingHint') }}</p></article>
      <article class="card capture-sequence"><header><strong>{{ t('deterministicCapture') }}</strong><span>{{ captureSequence.frames.length }} / {{ captureSequence.maximumFrames }}</span></header><div class="capture-settings"><label><span>{{ t('frameRate') }}</span><input v-model.number="settings.deterministicCapture.frameRate" type="number" min="1" max="240"></label><label><span>{{ t('sampleRate') }}</span><input v-model.number="settings.deterministicCapture.sampleRate" type="number" min="8000" max="192000"></label><label><span>{{ t('maximumFrames') }}</span><input v-model.number="settings.deterministicCapture.maximumFrames" type="number" min="1" max="18000"></label><label><span>{{ t('captureMemoryBudget') }}</span><input v-model.number="settings.deterministicCapture.memoryBudgetMb" type="number" min="16" max="2048"></label><label><span>{{ t('includeUi') }}</span><input v-model="settings.deterministicCapture.includeUi" type="checkbox"></label></div><div class="capture-actions"><button v-if="!captureSequence.active" class="primary" @click="beginCaptureSequence">● {{ t('startCapture') }}</button><button v-else class="danger" @click="stopDeterministicCapture()">■ {{ t('stopCapture') }}</button><button :disabled="captureSequence.active || !captureSequence.frames.length" @click="clearDeterministicCapture">{{ t('clearCapture') }}</button></div><progress :value="captureSequence.capturedBytes" :max="captureSequence.memoryBudgetBytes"></progress><p>{{ (captureSequence.capturedBytes/1048576).toFixed(1) }} / {{ (captureSequence.memoryBudgetBytes/1048576).toFixed(0) }} MB · {{ captureSequence.stoppedReason || t('captureReady') }}</p><div class="capture-frame-links"><a v-for="frame in captureSequence.frames.slice(-12)" :key="frame.index" :href="frame.dataUrl" :download="`nova-${captureSequence.name}-${String(frame.index).padStart(6,'0')}.png`">#{{ frame.index }} · {{ frame.timeSeconds.toFixed(3) }}s · {{ frame.audioSampleStart }}–{{ frame.audioSampleEnd }}</a></div></article>
      <article class="card issue-card"><header><strong>{{ t('productionIssues') }}</strong><span>{{ mediaReport.issues.length }}</span></header><p v-if="!mediaReport.issues.length" class="good">{{ t('productionMediaReady') }}</p><button v-for="item in mediaReport.issues" :key="`${item.code}:${item.message}`" :class="`status-${item.status}`" @click="focusMediaSubsystem(item.subsystem)"><strong>{{ item.code }} · {{ item.subsystem }}</strong><span>{{ item.message }}</span><small>{{ item.fix }}</small></button></article>
    </div>

    <div v-else-if="activeSection === 'diagnostics'" class="section-scroll diagnostics-layout">
      <article class="card"><header><strong>{{ t('renderDiagnostics') }}</strong><button @click="requestRenderCapture">{{ t('captureFrame') }}</button></header><label><span>{{ t('debugView') }}</span><select v-model="settings.debugView"><option>None</option><option>Overdraw</option><option>BatchBreaks</option><option>Lighting</option><option>Normals</option></select></label><div class="metric-grid"><span>GPU<strong>{{ stats.gpuMs === null ? 'n/a' : `${stats.gpuMs.toFixed(2)} ms` }}</strong></span><span>{{ t('drawCalls') }}<strong>{{ stats.drawCalls }}</strong></span><span>{{ t('renderBatches') }}<strong>{{ stats.batches }}</strong></span><span>{{ t('batchBreaks') }}<strong>{{ stats.batchBreaks }}</strong></span><span>{{ t('textureMemory') }}<strong>{{ (stats.textureMemoryBytes / 1048576).toFixed(1) }} MB</strong></span><span>{{ t('textureUploads') }}<strong>{{ stats.textureUploads }}</strong></span><span>{{ t('shaderCompiles') }}<strong>{{ stats.shaderCompiles }}</strong></span><span>{{ t('shaderFallbacks') }}<strong>{{ stats.shaderFallbacks }}</strong></span><span>{{ t('contextLosses') }}<strong>{{ stats.contextLosses }}</strong></span><span>{{ t('triangles') }}<strong>{{ stats.triangles }}</strong></span><span>{{ t('overdraw') }}<strong>{{ stats.overdraw }}</strong></span><span>{{ t('atlasPages') }}<strong>{{ stats.atlasPages }}</strong></span><span>{{ t('renderTargets') }}<strong>{{ stats.renderTargets }}</strong></span></div><dl><div v-for="(count,reason) in stats.batchBreakReasons" :key="reason"><dt>Batch: {{ reason }}</dt><dd>{{ count }}</dd></div><div v-for="pass in graph.passes" :key="pass.name"><dt>{{ pass.name }}</dt><dd>{{ pass.enabled ? `${pass.durationMs.toFixed(2)} ms · ${pass.drawCalls} DC` : t('disabled') }}</dd></div></dl></article>
      <article class="card"><header><strong>{{ t('renderSubsystems') }}</strong></header><dl><div><dt>{{ t('lights') }} / {{ t('shadowCasters') }}</dt><dd>{{ lightCount }} / {{ shadowCasterCount }}</dd></div><div><dt>{{ t('particles') }} CPU / GPU</dt><dd>{{ particles.cpuSimulated }} / {{ particles.gpuRendered }}</dd></div><div><dt>{{ t('activeQualityVolume') }}</dt><dd>{{ activeQuality.volumeId ?? t('none') }}</dd></div><div><dt>{{ t('residentTextures') }}</dt><dd>{{ stats.textures }}</dd></div><div><dt>{{ t('passTime') }}</dt><dd>{{ passTime.toFixed(2) }} ms</dd></div></dl><p>{{ t('renderSubsystemHint') }}</p></article>
      <article class="card capability-card"><header><strong>{{ t('capabilityReport') }}</strong><button @click="requestRendererReset">{{ t('resetRenderer') }}</button></header><p>{{ capability.target }} · {{ capability.backend }} · {{ capability.path }}</p><p v-if="capability.fallbackReason" class="warning">{{ capability.fallbackReason }}</p><dl><div><dt>Device</dt><dd>{{ capability.device }}</dd></div><div><dt>Driver</dt><dd>{{ capability.driver }}</dd></div><div><dt>API</dt><dd>{{ capability.apiVersion }}</dd></div><div><dt>Extensions</dt><dd>{{ capability.enabledExtensions.length }}</dd></div></dl><ul><li v-for="feature in capability.matrix" :key="feature.id" :class="feature.support === 'supported' ? 'good' : feature.support === 'limited' ? 'warning' : 'error'"><strong>{{ feature.label }}</strong><span>{{ feature.detail }}</span><button v-if="feature.support !== 'supported'" @click="applyCapabilityFix(feature.id)">{{ feature.fix }}</button></li></ul><small>{{ capabilityState.lastEvent }} · {{ capabilityState.contextLosses }} / {{ capabilityState.recoveries }}</small></article>
      <article class="card capture-list"><header><strong>{{ t('savedCaptures') }}</strong></header><div class="capture-compare"><select v-model.number="captureA"><option :value="0">A</option><option v-for="capture in graph.captures" :key="capture.id" :value="capture.id">{{ capture.createdAt }}</option></select><select v-model.number="captureB"><option :value="0">B</option><option v-for="capture in graph.captures" :key="capture.id" :value="capture.id">{{ capture.createdAt }}</option></select><button :disabled="!captureA || !captureB || captureA === captureB" @click="compareCaptures">{{ t('compareCaptures') }}</button></div><p v-if="lastDifference !== null">{{ t('pixelDifference') }}: {{ (lastDifference * 100).toFixed(4) }}%</p><a v-for="capture in graph.captures" :key="capture.id" :href="capture.dataUrl" :download="`nova-frame-${capture.id}.png`">{{ capture.createdAt }} · {{ capture.width }}×{{ capture.height }}</a></article>
      <article class="card recommendation-list"><header><strong>{{ t('renderRecommendations') }}</strong></header><div v-for="item in recommendations" :key="item.id" :class="item.severity"><strong>{{ recommendationTitle(item.id) }}</strong><span>{{ item.metric.toFixed(1) }} / {{ item.budget.toFixed(1) }}</span><small>{{ recommendationRemedy(item.id) }}</small></div></article>
      <article class="card atlas-preview"><header><strong>{{ t('atlasImportPreview') }}</strong><span>{{ atlasPages.length }} / {{ importPreview.length }}</span></header><div v-for="page in atlasPages" :key="page.key" class="preview-entry"><img v-if="page.thumbnail" :src="page.thumbnail" alt=""><span><strong>{{ page.key }} · {{ page.width }}×{{ page.height }}</strong><small>{{ page.regions }} {{ t('regions') }} · {{ (page.utilizationEstimate*100).toFixed(1) }}%</small><small v-if="page.warning" class="warning">{{ t('atlasUtilizationWarning') }}</small></span></div><details><summary>{{ t('textureImports') }}</summary><span v-for="asset in importPreview.slice(0,16)" :key="asset.uuid" :class="['preview-entry',{ warning: asset.warning }]"><img v-if="asset.thumbnail" :src="asset.thumbnail" alt=""><span>{{ asset.name }} · {{ asset.dimensions }} · {{ asset.profile }} · {{ asset.atlasGroup }}</span></span></details></article>
    </div>

    <div v-else class="section-scroll studio-grid">
      <article class="card"><header><strong>{{ t('qualityPreset') }}</strong></header><div class="preset-grid"><button v-for="preset in qualityPresets" :key="preset" :class="{ active: settings.qualityPreset === preset }" @click="applyQualityPreset(preset)">{{ preset }}</button></div><label><span>{{ t('rendererPath') }}</span><select v-model="settings.rendererPath" @change="requestRendererReset"><option>Auto</option><option>Native</option><option>Compatibility</option></select></label><label><span>{{ t('unsupportedFeatures') }}</span><select v-model="settings.unsupportedPolicy"><option>WarnAndFallback</option><option>Block</option></select></label><label><span>{{ t('pixelPerfect') }}</span><input v-model="settings.pixelSnap" type="checkbox"></label><label><span>{{ t('renderQuality') }}</span><input v-model.number="settings.maximumPixelRatio" type="number" min="1" max="4" step=".25"></label><label><span>{{ t('colorSpace') }}</span><select v-model="settings.colorSpace"><option>sRGB</option><option>Linear</option></select></label><p>{{ t('qualityPresetHint') }}</p></article>
      <article class="card quality-volumes"><header><strong>{{ t('qualityVolumes') }}</strong><button :disabled="settings.qualityVolumes.length>=64" @click="addQualityVolume">＋</button></header><p>{{ t('qualityVolumeHint') }}</p><div v-for="volume in settings.qualityVolumes" :key="volume.id" class="volume-card"><header><input v-model="volume.enabled" type="checkbox"><input v-model.trim="volume.name" maxlength="80"><button @click="removeQualityVolume(volume.id)">×</button></header><label><span>{{ t('qualityPreset') }}</span><select v-model="volume.preset"><option v-for="preset in qualityPresets" :key="preset">{{ preset }}</option></select></label><label><span>{{ t('priority') }}</span><input v-model.number="volume.priority" type="number" min="-1000" max="1000"></label><label><span>{{ t('center') }} X/Y</span><span class="pair"><input v-model.number="volume.center.x" type="number"><input v-model.number="volume.center.y" type="number"></span></label><label><span>{{ t('size') }} W/H</span><span class="pair"><input v-model.number="volume.size.x" type="number" min=".001"><input v-model.number="volume.size.y" type="number" min=".001"></span></label></div><p v-if="!settings.qualityVolumes.length">{{ t('noQualityVolumes') }}</p></article>
      <article class="card"><header><strong>{{ t('projectRenderBudgets') }}</strong></header><label><span>{{ t('drawCalls') }}</span><input v-model.number="settings.budgets.drawCalls" type="number" min="1"></label><label><span>{{ t('textureMemory') }} (MB)</span><input v-model.number="settings.budgets.textureMemoryMb" type="number" min="1"></label><label><span>Overdraw</span><input v-model.number="settings.budgets.overdraw" type="number" min="1" step=".25"></label><label><span>{{ t('gpuFrame') }} (ms)</span><input v-model.number="settings.budgets.gpuMs" type="number" min=".1" step=".1"></label><label><span>{{ t('particles') }} (ms)</span><input v-model.number="settings.budgets.particleMs" type="number" min=".05" step=".05"></label></article>
      <article v-if="capability.backend === 'WebGL2'" class="card"><header><strong>{{ t('postProcessing') }}</strong><input v-model="settings.postProcessing.enabled" type="checkbox"></header><label><span>{{ t('postMaterial') }}</span><select v-model="activePostPreset.userMaterial" @change="syncPostPreset"><option :value="null">{{ t('none') }}</option><option v-for="asset in materialAssets" :key="asset.uuid" :value="assetReference(asset.uuid)">{{ asset.name }}</option></select></label><label><span>{{ t('exposure') }}</span><input v-model.number="activePostPreset.exposure" type="number" min="-8" max="8" step="0.1" @change="syncPostPreset"></label><label><span>{{ t('contrast') }}</span><input v-model.number="activePostPreset.contrast" type="number" min="0" max="4" step="0.05" @change="syncPostPreset"></label><label><span>{{ t('saturation') }}</span><input v-model.number="activePostPreset.saturation" type="number" min="0" max="4" step="0.05" @change="syncPostPreset"></label><label><span>{{ t('vignette') }}</span><input v-model.number="activePostPreset.vignette" type="range" min="0" max="1" step="0.05" @input="syncPostPreset"></label><label><span>{{ t('bloom') }}</span><input v-model.number="activePostPreset.bloom" type="range" min="0" max="2" step="0.05" @input="syncPostPreset"></label><label><span>{{ t('blur') }}</span><input v-model.number="activePostPreset.blur" type="range" min="0" max="16" step="0.25" @input="syncPostPreset"></label></article>
      <article v-else class="card warning-card"><strong>{{ t('fallbackRendererActive') }}</strong><p>{{ t('fallbackRendererDescription') }}</p></article>
    </div>
  </section>
</template>

<script setup lang="ts">
import { computed, nextTick, ref, watch } from 'vue'
import { assetReference, assetState, createTextAsset, readTextAsset, updateTextAsset } from '../assets/AssetDatabase'
import { t } from '../i18n'
import { MATERIAL_INCLUDE_LIBRARY, analyzeMaterialShader, defaultMaterial, normalizeMaterial, renderMaterialPreview, resolvedMaterialFragment, serializeMaterial, type Material2DResource, type MaterialUniformType, type ShaderDiagnostic } from '../renderer/materials'
import { defaultMaterialGraph, defaultMaterialLayer, materialCapabilityPreview, validateMaterialGraph, type MaterialLayerKind } from '../renderer/materialGraph'
import { defaultParticleGraph, normalizeParticleGraph, particleGraphValues, type ParticleGraphDocument } from '../renderer/particleGraph'
import { activeRenderQuality as activeQuality, applyQualityPreset, estimatePostProcessCost, renderingSettings as settings, updateActivePostProcess, type RenderQualityPreset } from '../renderer/renderSettings'
import { clearDeterministicCapture, compareRenderCaptures, renderGraphState as graph, requestRenderCapture, startDeterministicCapture, stopDeterministicCapture } from '../renderer/renderGraph'
import { atlasPreviews, importPreviews, renderRecommendations } from '../renderer/renderOptimization'
import { queryRendererCapabilities, rendererCapabilityState as capabilityState, requestRendererReset } from '../renderer/capabilities'
import { particleDiagnostics as particles } from '../runtime/particles'
import { buildMediaProductionReport, type MediaProductionProfile } from '../runtime/mediaProduction26'
import { editorState } from '../store/editor'
import { physicsState, pushHistory } from '../store/physics'
import { ParticleEmitter2D, copyComponentValues, pasteComponentValues } from '../world/components'
import MaterialGraphEditor from './MaterialGraphEditor.vue'
import ParticleGraphEditor from './ParticleGraphEditor.vue'

type SectionId = 'lighting' | 'materials' | 'shaders' | 'graph' | 'particles' | 'post' | 'production' | 'diagnostics' | 'quality'
const sections = [{ id: 'lighting' as const, label: 'lighting' }, { id: 'materials' as const, label: 'materials' }, { id: 'shaders' as const, label: 'shaders' }, { id: 'graph' as const, label: 'visualMaterialGraph' }, { id: 'particles' as const, label: 'particles' }, { id: 'post' as const, label: 'postProcessing' }, { id: 'production' as const, label: 'productionMedia' }, { id: 'diagnostics' as const, label: 'diagnostics' }, { id: 'quality' as const, label: 'quality' }]
const activeSection = ref<SectionId>('lighting'), advancedMode = ref(false)
const previewCanvas = ref<HTMLCanvasElement | null>(null), shaderPreviewCanvas = ref<HTMLCanvasElement | null>(null)
const materialAssets = computed(() => assetState.records.filter(asset => asset.assetType === 'material')), imageAssets = computed(() => assetState.records.filter(asset => asset.assetType === 'image'))
const particleAssets = computed(() => assetState.records.filter(asset => asset.assetType === 'particleSystem')), selectedParticleGuid = ref('')
const selectedGuid = ref(assetState.selectedGuid && materialAssets.value.some(asset => asset.uuid === assetState.selectedGuid) ? assetState.selectedGuid : materialAssets.value[0]?.uuid ?? '')
const parentMaterialAssets = computed(() => materialAssets.value.filter(asset => asset.uuid !== selectedGuid.value))
const material = ref<Material2DResource>(defaultMaterial()), diagnostics = ref<ShaderDiagnostic[]>([]), selectedLayerId = ref('')
const uniformsJson = ref('{}'), texturesJson = ref('{}'), captureA = ref(0), captureB = ref(0), lastDifference = ref<number | null>(null)
const stats = computed(() => editorState.rendererStats), graphDiagnostics = computed(() => material.value.graph ? validateMaterialGraph(material.value.graph) : []), hasErrors = computed(() => diagnostics.value.some(item => item.severity === 'error') || graphDiagnostics.value.some(item => item.severity === 'error'))
const includeLibrary = MATERIAL_INCLUDE_LIBRARY, qualityPresets: RenderQualityPreset[] = ['Performance', 'Balanced', 'High', 'Ultra', 'PixelArt']
const capability = computed(() => capabilityState.report ?? queryRendererCapabilities(stats.value.backend))
const layerKinds: MaterialLayerKind[] = ['Tint', 'Mask', 'Gradient', 'Palette', 'Outline', 'Dissolve', 'Distortion']
const materialGraphCapability = computed(() => materialCapabilityPreview(material.value.graph ?? defaultMaterialGraph(material.value.target), material.value.layers, capability.value.backend))
const selectedLayer = computed(() => material.value.layers.find(layer => layer.id === selectedLayerId.value) ?? null)
const materialGraphRecommendation = computed(() => materialGraphCapability.value.fallbackNodes.length ? t('canvasMaterialFallback') : materialGraphCapability.value.gpuCost.score > 24 ? t('materialBudgetReduce') : t('materialBudgetGood'))
const particleGraph = ref<ParticleGraphDocument>(defaultParticleGraph())
const activePostPreset = computed(() => settings.postProcessing.presets.find(item => item.id === settings.postProcessing.activePreset)?.values ?? settings.postProcessing)
const postCost = computed(() => estimatePostProcessCost(activePostPreset.value))
const recommendations = computed(() => renderRecommendations(stats.value, assetState.records, settings))
const mediaReport = computed(() => buildMediaProductionReport(assetState.records, physicsState.world.entities, stats.value, physicsState.audioSettings))
const captureSequence = graph.sequence
const lightCount = computed(() => physicsState.world.entities.filter(entity=>entity.hasComponent('Light2D')).length), shadowCasterCount = computed(() => physicsState.world.entities.filter(entity=>entity.hasComponent('ShadowCaster2D')).length), passTime = computed(() => graph.passes.reduce((sum,pass)=>sum+(pass.enabled?pass.durationMs:0),0))
const atlasPages = computed(() => atlasPreviews(assetState.atlasPages)), importPreview = computed(() => importPreviews(assetState.records))
let timer = 0

watch(selectedGuid, loadMaterial, { immediate: true }); watch(activeSection, () => void nextTick(renderPreview))
watch(selectedParticleGuid, loadParticleGraph, { immediate: true })
function loadMaterial(guid: string) { const source = readTextAsset(guid); try { material.value = normalizeMaterial(source ? JSON.parse(source) : defaultMaterial()) } catch { material.value = defaultMaterial() } syncAdvanced(); schedulePreview() }
function syncAdvanced() { uniformsJson.value = JSON.stringify(material.value.uniforms, null, 2); texturesJson.value = JSON.stringify(material.value.textures, null, 2) }
function schedulePreview() { clearTimeout(timer); material.value = normalizeMaterial(material.value); syncAdvanced(); timer = window.setTimeout(() => void nextTick(renderPreview), 120) }
function renderPreview() { const canvas = activeSection.value === 'shaders' ? shaderPreviewCanvas.value : previewCanvas.value; diagnostics.value = canvas ? renderMaterialPreview(canvas, material.value) : diagnostics.value }
function parseObject(source: string): Record<string, unknown> | null { try { const value = JSON.parse(source); return value && typeof value === 'object' && !Array.isArray(value) ? value : null } catch { return null } }
function applyUniforms() { const value = parseObject(uniformsJson.value); if (!value) { diagnostics.value = [{ line: 1, severity: 'error', message: 'Uniforms must be a JSON object.' }]; return } material.value = normalizeMaterial({ ...material.value, uniforms: value }); schedulePreview() }
function applyTextures() { const value = parseObject(texturesJson.value); if (!value) { diagnostics.value = [{ line: 1, severity: 'error', message: 'Textures must be a JSON object.' }]; return } material.value = normalizeMaterial({ ...material.value, textures: value }); schedulePreview() }
function createMaterial() { const asset = createTextAsset(t('newMaterial'), 'material', serializeMaterial(defaultMaterial()), 'Assets/Materials'); selectedGuid.value = asset.uuid; assetState.selectedGuid = asset.uuid; pushHistory('Create material') }
function saveMaterial() { const resolved = resolvedMaterialFragment(material.value); diagnostics.value = [...resolved.diagnostics, ...analyzeMaterialShader(resolved.source)]; renderPreview(); if (!selectedGuid.value || hasErrors.value) return; updateTextAsset(selectedGuid.value, serializeMaterial(material.value)); assetState.selectedGuid = selectedGuid.value; pushHistory('Save material') }
function setToggle(name: string, event: Event) { material.value.uniforms[name] = (event.target as HTMLInputElement).checked; schedulePreview() }
function setTexture(name: string, event: Event) { material.value.textures[name] = (event.target as HTMLSelectElement).value || null; schedulePreview() }
function setScalar(name: string, event: Event, integer = false) { const value = Number((event.target as HTMLInputElement | HTMLSelectElement).value); material.value.uniforms[name] = integer ? Math.round(value) : value; schedulePreview() }
function vectorLength(type: MaterialUniformType) { return type === 'vector2' ? 2 : type === 'vector3' ? 3 : 4 }
function uniformComponent(name: string, index: number) { const value = material.value.uniforms[name]; return Array.isArray(value) ? value[index] ?? 0 : 0 }
function setUniformComponent(name: string, index: number, event: Event) { const current = material.value.uniforms[name], value = Array.isArray(current) ? [...current] : [0, 0, 0, 0]; value[index] = Number((event.target as HTMLInputElement).value); material.value.uniforms[name] = value; schedulePreview() }
function uniformColor(name: string) { const value = material.value.uniforms[name], channels = Array.isArray(value) ? value : [1, 1, 1, 1]; return `#${channels.slice(0, 3).map(channel => Math.round(Math.min(1, Math.max(0, channel)) * 255).toString(16).padStart(2, '0')).join('')}` }
function setUniformColor(name: string, event: Event) { const value = (event.target as HTMLInputElement).value; material.value.uniforms[name] = [1, 3, 5].map(index => parseInt(value.slice(index, index + 2), 16) / 255).concat([1]); schedulePreview() }
function toggleInclude(name: string) { const index = material.value.includes.indexOf(name); if (index >= 0) material.value.includes.splice(index, 1); else material.value.includes.push(name); schedulePreview() }
function enableMaterialGraph() { material.value.graph = defaultMaterialGraph(material.value.target); schedulePreview(); pushHistory('Create visual material graph') }
function addLayer(kind: MaterialLayerKind) { if (material.value.layers.length >= 16) return; const layer = defaultMaterialLayer(kind, material.value.layers.length); material.value.layers.push(layer); selectedLayerId.value = layer.id; schedulePreview(); pushHistory(`Add ${kind} material layer`) }
function removeLayer(index: number) { if (index < 0 || index >= material.value.layers.length) return; const [removed] = material.value.layers.splice(index, 1); if (removed.id === selectedLayerId.value) selectedLayerId.value = material.value.layers[Math.min(index, material.value.layers.length - 1)]?.id ?? ''; schedulePreview(); pushHistory('Remove material layer') }
function moveLayer(index: number, offset: number) { const target = index + offset; if (index < 0 || target < 0 || target >= material.value.layers.length) return; const [layer] = material.value.layers.splice(index, 1); material.value.layers.splice(target, 0, layer); schedulePreview(); pushHistory('Reorder material layer') }
function focusShaderLine(line: number) { editorState.statusText = `${t('shaderSource')} · L${line}` }
function hex(color: { r: number; g: number; b: number }) { return `#${[color.r, color.g, color.b].map(value => Math.round(value).toString(16).padStart(2, '0')).join('')}` }
function setColor(target: { r: number; g: number; b: number }, event: Event) { const value = (event.target as HTMLInputElement).value; target.r = parseInt(value.slice(1, 3), 16); target.g = parseInt(value.slice(3, 5), 16); target.b = parseInt(value.slice(5, 7), 16) }
function unitColorHex(color: readonly number[]) { return `#${color.slice(0,3).map(value => Math.round(Math.min(1,Math.max(0,value))*255).toString(16).padStart(2,'0')).join('')}` }
function setLayerColor(target: [number,number,number,number], event: Event) { const value = (event.target as HTMLInputElement).value; [target[0],target[1],target[2]] = [1,3,5].map(index => parseInt(value.slice(index,index+2),16)/255); schedulePreview() }
async function compareCaptures() { lastDifference.value = await compareRenderCaptures(captureA.value, captureB.value) }
function openParticleInspector() { const emitter = physicsState.world.entities.find(entity => entity.hasComponent('ParticleEmitter2D')); if (emitter) { physicsState.selectedEntityIds.splice(0, physicsState.selectedEntityIds.length, emitter.id); physicsState.selectedEntityId = emitter.id; editorState.bottomPanelOpen = false } else editorState.statusText = t('noParticleEmitter') }
function firstEmitter() { return physicsState.world.entities.map(entity => entity.getComponent<ParticleEmitter2D>('ParticleEmitter2D')).find(Boolean) ?? null }
function graphFromEmitter(emitter: ParticleEmitter2D): ParticleGraphDocument { const graph = defaultParticleGraph(); const values = (kind: string) => graph.modules.find(item => item.kind === kind)!.values; Object.assign(values('Spawn'), { rate: emitter.emissionRate, burst: emitter.burst, lifetime: emitter.lifetime, maximum: emitter.maxParticles }); Object.assign(values('Shape'), { shape: emitter.emissionShape, size: [emitter.shapeSize.x, emitter.shapeSize.y], radius: emitter.shapeRadius }); Object.assign(values('Velocity'), { minimum: [emitter.initialVelocityMin.x, emitter.initialVelocityMin.y], maximum: [emitter.initialVelocityMax.x, emitter.initialVelocityMax.y] }); Object.assign(values('Force'), { gravity: [emitter.gravity.x, emitter.gravity.y] }); Object.assign(values('Size'), { start: emitter.startScale, end: emitter.endScale }); Object.assign(values('Collision'), { mode: emitter.collisionMode, restitution: emitter.collisionRestitution }); Object.assign(values('Events'), { signal: emitter.eventSignal }); Object.assign(values('SubEmitter'), { emitterUuid: emitter.subEmitterUuid, count: emitter.subEmitterCount }); Object.assign(values('Trail'), { length: emitter.trailLength, width: emitter.trailWidth }); Object.assign(values('Renderer'), { material: emitter.material, blend: emitter.blendMode }); graph.modules.find(item=>item.kind==='Collision')!.enabled=emitter.collisionMode!=='None'; graph.modules.find(item=>item.kind==='Events')!.enabled=Boolean(emitter.eventSignal); graph.modules.find(item=>item.kind==='SubEmitter')!.enabled=Boolean(emitter.subEmitterUuid); graph.modules.find(item=>item.kind==='Trail')!.enabled=emitter.trailEnabled; graph.simulation=emitter.simulationBackend; return normalizeParticleGraph(graph) }
function createParticleAsset() { const emitter = firstEmitter(); if (!emitter) return openParticleInspector(); particleGraph.value = graphFromEmitter(emitter); const asset = createTextAsset(t('particleSystemAsset'), 'particleSystem', JSON.stringify({ format: 'nova-particle-system', version: 2, graph: particleGraph.value, values: copyComponentValues(emitter) }, null, 2), 'Assets/Particles'); selectedParticleGuid.value = asset.uuid; pushHistory('Create particle graph asset') }
function loadParticleGraph(guid: string) { const source = readTextAsset(guid); if (!source) { particleGraph.value = firstEmitter() ? graphFromEmitter(firstEmitter()!) : defaultParticleGraph(); return } try { const document = JSON.parse(source) as { graph?: unknown; values?: Record<string, unknown> }; if (document.graph) particleGraph.value = normalizeParticleGraph(document.graph); else if (document.values) { const temporary = new ParticleEmitter2D(); pasteComponentValues(temporary, document.values); particleGraph.value = graphFromEmitter(temporary) } else particleGraph.value = defaultParticleGraph() } catch { particleGraph.value = defaultParticleGraph(); editorState.statusText = t('invalidParticleAsset') } }
function saveParticleAsset() { const emitter = firstEmitter(); if (!selectedParticleGuid.value) return; updateTextAsset(selectedParticleGuid.value, JSON.stringify({ format: 'nova-particle-system', version: 2, graph: normalizeParticleGraph(particleGraph.value), values: emitter ? copyComponentValues(emitter) : {} }, null, 2)); pushHistory('Save particle graph asset') }
function applyParticleAsset() { const emitter = firstEmitter(); if (!emitter || !selectedParticleGuid.value) return; pasteComponentValues(emitter, particleGraphValues(particleGraph.value) as Record<string, unknown>); emitter.particleSystemAsset = assetReference(selectedParticleGuid.value); pushHistory('Apply particle graph asset') }
function applyActivePostPreset() { Object.assign(settings.postProcessing, activePostPreset.value); updateActivePostProcess(); pushHistory('Apply post-process preset') }
function syncPostPreset() { Object.assign(settings.postProcessing, activePostPreset.value); updateActivePostProcess() }
function duplicatePostPreset() { const source = activePostPreset.value, id = `preset-${Date.now().toString(36)}`; settings.postProcessing.presets.push({ id, name: `${settings.postProcessing.presets.find(item=>item.id===settings.postProcessing.activePreset)?.name ?? t('preset')} 2`, values: { ...source } }); settings.postProcessing.activePreset = id; applyActivePostPreset() }
function addPostVolume() { const id = `volume-${Date.now().toString(36)}`; settings.postProcessing.volumes.push({ id, name: `${t('cameraVolume')} ${settings.postProcessing.volumes.length + 1}`, enabled: true, center: { x: 0, y: 0 }, size: { x: 10, y: 10 }, blendDistance: 1, priority: 0, presetId: settings.postProcessing.activePreset }); pushHistory('Add post-process camera volume') }
function removePostVolume(id: string) { const index = settings.postProcessing.volumes.findIndex(item => item.id === id); if (index >= 0) { settings.postProcessing.volumes.splice(index, 1); pushHistory('Remove post-process camera volume') } }
function addQualityVolume(){const id=`quality-${Date.now().toString(36)}`;settings.qualityVolumes.push({id,name:`${t('qualityVolume')} ${settings.qualityVolumes.length+1}`,enabled:true,center:{x:0,y:0},size:{x:20,y:20},priority:0,preset:settings.qualityPreset,maximumPixelRatio:null,particleBudget:null,shadowQuality:null});pushHistory('Add render quality volume')}
function removeQualityVolume(id:string){const index=settings.qualityVolumes.findIndex(volume=>volume.id===id);if(index>=0){settings.qualityVolumes.splice(index,1);pushHistory('Remove render quality volume')}}
function recommendationTitle(id: string) { return t(`renderRecommendation_${id}`) }
function recommendationRemedy(id: string) { return t(`renderRemedy_${id}`) }
function applyCapabilityFix(id: string) { if (id === 'materials' || id === 'post') { settings.postProcessing.enabled = false; activePostPreset.value.userMaterial = null; settings.postProcessing.userMaterial = null; updateActivePostProcess() } else if (id === 'gpu-timing') settings.debugView = 'None'; else settings.rendererPath = 'Auto'; editorState.statusText = capability.value.matrix.find(item => item.id === id)?.fix ?? 'Renderer setting updated' }
function applyMediaProfile(profile: MediaProductionProfile) { applyQualityPreset(profile === 'LowEnd' ? 'Performance' : 'Balanced'); pushHistory(`Apply ${profile} production-media profile`, 'project:rendering') }
function beginCaptureSequence() { startDeterministicCapture({ name: 'cinematic', ...settings.deterministicCapture }) }
function focusMediaSubsystem(subsystem: 'Rendering' | 'Animation' | 'Audio' | 'Cinematic') { if (subsystem === 'Rendering') activeSection.value = 'diagnostics'; else { editorState.activeWorkspace = subsystem === 'Animation' || subsystem === 'Cinematic' ? 'animation' : 'ui'; editorState.currentPage = 'scene'; editorState.statusText = subsystem === 'Audio' ? t('openAudioWorkspaceHint') : t('openAnimationWorkspace') } }
</script>

